ForbiddenView = class("ForbiddenView", ViewBase)

function ForbiddenView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "ForbiddenViewAction")
end

function ForbiddenView:Awake()
    self.allType = ForbiddenDataManager:Get():GetTitleType()
    self:CacheViewData()
    self:InitViewBtn()
end

function ForbiddenView:OnOpen()
    self.curSelectType = PartType.All
    self:UpdateChooseBtn()
    self:UpdateList()
end

function ForbiddenView:CacheViewData()
    self.TableBagSVC = UIUtil.GetTypeChildWightInputPath("TableBagSVC", self.gameObject, typeof(MoreRowScrollView))
    self.ChooseBtnSVC = UIUtil.GetTypeChildWightByParent("ChooseBtnSVC", self.gameObject, typeof(MoreRowScrollView))
end

function ForbiddenView:UpdateChooseBtn()

    local UpdateFunc = function(dataIndex, itemObj, scroll)
        local type = self.allType[dataIndex + 1]
        local typename = type == PartType.All and CommonHelper:GetTempStr_Default(TemplateStringID.ForbiddenALL) or CommonHelper:GetGoodsTypeName(GoodsType1.Part, type)
        CommonHelper:SetGameObjectActive("choose", itemObj, self.curSelectType == type)
        CommonHelper:SetGameObjectActive("common", itemObj, self.curSelectType ~= type)

        CommonHelper:SetText("choose/###Text", itemObj, typename)
        CommonHelper:SetText("common/###Text", itemObj, typename)
        CommonHelper:HButtonSetCallback("ItemBtn", itemObj, function(btn)
            self.curSelectType = type
            self:UpdateChooseBtn()
            self:UpdateList()
        end)
    end
    CommonHelper:InitMoreRowScrollView(self.ChooseBtnSVC, #self.allType, 1, UpdateFunc, true, nil, false)

end

function ForbiddenView:UpdateList()
    local ForbiddenTable = ForbiddenDataManager:Get():GetForbiddenTable()
    local count = 0
    if self.curSelectType == PartType.All then
        for _, tab in pairs(ForbiddenTable) do
            for _, _ in pairs(tab) do
                count = count + 1
            end
        end
    else
        for _, _ in pairs(ForbiddenTable[self.curSelectType]) do
            count = count + 1
        end
    end

    CommonHelper:InitMoreRowScrollView(self.TableBagSVC, count, 1, function(itemIndex, itemChild, scroll)
        local index = itemIndex + 1
        local parttype = self.curSelectType
        local subtype = nil
        local datalist = nil
        local tempIndex = 1
        local find=false
        if parttype == PartType.All then
            for _parttype, tab in pairs(ForbiddenTable) do
                for _subtype, _datalist in pairs(tab) do
                    if tempIndex == index then
                        subtype = _subtype
                        parttype = _parttype
                        datalist = _datalist
                        find=true
                        break
                    else
                        tempIndex = tempIndex + 1
                    end
                end
                if find then break end
            end
        else
            for _subtype, _datalist in pairs(ForbiddenTable[parttype]) do
                if tempIndex == index then
                    subtype = _subtype
                    datalist = _datalist
                    break
                else
                    tempIndex = tempIndex + 1
                end
            end
        end

        CommonHelper:SetText("###partsubtype", itemChild, CommonHelper:GetGoodsTypeName(GoodsType1.Part,parttype, subtype))

        local ItemSVC = UIUtil.GetTypeChildWightInputPath("ItemSVC", itemChild, typeof(MoreRowScrollView))
        CommonHelper:InitMoreRowScrollView(ItemSVC, #datalist, 1, function(dataIndex, itemObject, scroll)
            ---@type ForbiddenData
            local _data = datalist[dataIndex + 1]
            local ItemObj = UIUtil.GetChild("ItemCom_202", itemObject)
            CommonHelper:SetItemComGroup(ItemObj, self:GetUIModuleID(), _data.baseCfg.C_ID, nil, function()
                CommonHelper:ShowPartInfoByCfgId(_data.baseCfg.C_ID, self:GetUIModuleID())
            end)
            ---@type dictpartbase_config_cell
            CommonHelper:SetText("###partname", itemObject, ClientDataManager:Get():GetTemplateString(_data.partCfg.partname))

        end)
    end, false)
end

